/// The public names of the C or builtin module `name`, `None` when it is not one.
pub fn names(name: &str) -> Option<&'static [&'static str]> {
    C_MODULES
        .binary_search_by_key(&name, |(module, _)| module)
        .ok()
        .map(|at| C_MODULES[at].1)
}
